    Q2 : BOOL;
    Q3 : BOOL;
    Q4 : BOOL;
    Q5 : BOOL;
    Q6 : BOOL;
    Q7 : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF SetIn OR RST THEN
    Q0 := NOT RST;
    Q1 := Q0;
    Q2 := Q0;
    Q3 := Q0;
    Q4 := Q0;
    Q5 := Q0;
    Q6 := Q0;
    Q7 := Q0;
ELSIF CLK AND NOT Edge THEN
    IF DN THEN
        Q0 := Q1;
        Q1 := Q2;
        Q2 := Q3;
        Q3 := Q4;
        Q4 := Q5;
        Q5 := Q6;
        Q6 := Q7;
        Q7 := D7;
    ELSE
        Q7 := Q6;
        Q6 := Q5;
        Q5 := Q4;
        Q4 := Q3;
        Q3 := Q2;
        Q2 := Q1;
        Q1 := Q0;
        Q0 := D0;
    END_IF;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

