FUNCTION_BLOCK FIFO_16
VAR_INPUT
    DIN : DWORD;
    E : BOOL := TRUE;
    RD : BOOL;
    WD : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    DOUT : DWORD;
    EMPTY : BOOL;
    FULL : BOOL;
END_VAR
VAR
    Fifo : ARRAY[0..15] OF DWORD;
    Pr : INT;
    Pw : INT;
END_VAR

IF RST THEN
    Pw := Pr;
    FULL := FALSE;
    EMPTY := TRUE;
    DOUT := DWORD#0;
ELSIF E THEN
    IF NOT EMPTY AND RD THEN
        DOUT := Fifo[Pr];
        IF Pr >= INT#15 THEN
            Pr := INT#0;
        ELSE
            Pr := Pr + INT#1;
        END_IF;
        EMPTY := Pr = Pw;
        FULL := FALSE;
    END_IF;
    IF NOT FULL AND WD THEN
        Fifo[Pw] := DIN;
        IF Pw >= INT#15 THEN
            Pw := INT#0;
        ELSE
            Pw := Pw + INT#1;
        END_IF;
        FULL := Pw = Pr;
        EMPTY := FALSE;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

