ELSIF E THEN
    IF NOT EMPTY AND RD THEN
        DOUT := Fifo[Pr];
        IF Pr >= INT#31 THEN
            Pr := INT#0;
        ELSE
            Pr := Pr + INT#1;
        END_IF;
