FUNCTION STATUS_TO_ESR : ESR_DATA
VAR_INPUT
    status : BYTE;
    adress : STRING(10);
    DT_in : DT;
    TS : TIME;
END_VAR
VAR
    Result : ESR_DATA;
END_VAR

IF status < BYTE#100 THEN
    Result.TYP := BYTE#1;
ELSIF status < BYTE#200 THEN
    Result.TYP := BYTE#2;
ELSE
    Result.TYP := BYTE#3;
END_IF;
Result.ADRESS := adress;
Result.DS := DT_in;
Result.TS := TS;
Result.DATA[0] := status;
STATUS_TO_ESR := Result;
END_FUNCTION

