/root/libraries/oscat/src/10_geometric_f.content:
(* OSCAT BASIC 3.33 geometric helpers. *)

FUNCTION CIRCLE_A : REAL
VAR_INPUT
    RX : REAL;
    AX : REAL;
END_VAR

CIRCLE_A := RX * RX * REAL#8.726646E-3 * AX;
END_FUNCTION

FUNCTION CIRCLE_C : REAL
VAR_INPUT
    RX : REAL;
    AX : REAL;
END_VAR

CIRCLE_C := REAL#1.7453293E-2 * RX * AX;
END_FUNCTION

FUNCTION CIRCLE_SEG : REAL
VAR_INPUT
    RX : REAL;
    HX : REAL;
END_VAR
VAR
    Angle : REAL;
END_VAR

CIRCLE_SEG := REAL#0.0;
IF RX > REAL#0.0 THEN
    Angle := REAL#2.0 * ACOS(IN := REAL#1.0 - LIMIT(MN := REAL#0.0, IN := HX / RX, MX := REAL#2.0));
    CIRCLE_SEG := (Angle - SIN(IN := Angle)) * RX * RX * REAL#0.5;
END_IF;
END_FUNCTION

FUNCTION CONE_V : REAL
VAR_INPUT
    RX : REAL;
    HX : REAL;
END_VAR

CONE_V := REAL#1.047197551 * RX * RX * HX;
END_FUNCTION

FUNCTION ELLIPSE_A : REAL
VAR_INPUT
    R1 : REAL;
    R2 : REAL;
END_VAR

ELLIPSE_A := REAL#3.141592653589793 * R1 * R2;
END_FUNCTION

FUNCTION ELLIPSE_C : REAL
VAR_INPUT
    R1 : REAL;
    R2 : REAL;
END_VAR

ELLIPSE_C := REAL#3.141592653589793 * (REAL#3.0 * (R1 + R2) - SQRT(IN := (REAL#3.0 * R1 + R2) * (REAL#3.0 * R2 + R1)));
END_FUNCTION

FUNCTION SPHERE_V : REAL
VAR_INPUT
    RX : REAL;
END_VAR

SPHERE_V := REAL#4.188790205 * RX * RX * RX;
END_FUNCTION

FUNCTION TRIANGLE_A : REAL
VAR_INPUT
    S1 : REAL;
    A : REAL;
    S2 : REAL;
    S3 : REAL;
END_VAR

IF A = REAL#0.0 THEN
    TRIANGLE_A := SQRT(IN := (S1 + S2 + S3) * (S1 + S2 - S3) * (S2 + S3 - S1) * (S3 + S1 - S2)) * REAL#0.25;
ELSE
    TRIANGLE_A := S1 * S2 * SIN(IN := RAD(DEG := A)) * REAL#0.5;
END_IF;
END_FUNCTION

/root/libraries/oscat/src/05_mathematics.content:
(* OSCAT BASIC 3.33 Chapter 5 Mathematics helpers. *)

FUNCTION ACOSH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ACOSH := LN(SQRT(X * X - 1.0) + X);
END_FUNCTION

FUNCTION ACOTH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ACOTH := LN((X + 1.0) / (X - 1.0)) * 0.5;
END_FUNCTION

FUNCTION AGDF : REAL
VAR_INPUT
    X : REAL;
END_VAR
AGDF := LN((1.0 + SIN(X)) / COS(X));
END_FUNCTION

FUNCTION ASINH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ASINH := LN(SQRT(X * X + 1.0) + X);
END_FUNCTION

FUNCTION ATAN2 : REAL
VAR_INPUT
    Y : REAL;
    X : REAL;
END_VAR
IF X > 0.0 THEN
    ATAN2 := ATAN(Y / X);
ELSIF X < 0.0 THEN
    IF Y >= 0.0 THEN
        ATAN2 := ATAN(Y / X) + MATH.PI;
    ELSE
        ATAN2 := ATAN(Y / X) - MATH.PI;
    END_IF;
ELSIF Y > 0.0 THEN
    ATAN2 := MATH.PI05;
ELSIF Y < 0.0 THEN
    ATAN2 := -MATH.PI05;
ELSE
    ATAN2 := 0.0;
END_IF;
END_FUNCTION

FUNCTION ATANH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ATANH := LN((X + 1.0) / (1.0 - X)) * 0.5;
END_FUNCTION

FUNCTION BETA : REAL
VAR_INPUT
    X : REAL;
    Y : REAL;
END_VAR
BETA := GAMMA(X := X) * GAMMA(X := Y) / GAMMA(X := X + Y);
END_FUNCTION

FUNCTION BINOM : DINT
VAR_INPUT
    N : INT;
    K : INT;
END_VAR
VAR
    Result : DINT;
    WorkN : INT;
    WorkK : INT;
    I : INT;
END_VAR
WorkN := N;
WorkK := K;
IF 2 * WorkK > WorkN THEN
    WorkK := WorkN - WorkK;
END_IF;
IF WorkK > WorkN THEN
    BINOM := DINT#0;
ELSIF WorkK = 0 OR WorkK = WorkN THEN
    BINOM := DINT#1;
ELSIF WorkK = 1 THEN
    BINOM := INT_TO_DINT(WorkN);
ELSE
    Result := INT_TO_DINT(WorkN);
    WorkN := WorkN + 1;
    FOR I := 2 TO WorkK DO
        Result := Result * INT_TO_DINT(WorkN - I) / INT_TO_DINT(I);
    END_FOR;
    BINOM := Result;
END_IF;
END_FUNCTION

FUNCTION CAUCHY : REAL
VAR_INPUT
    X : REAL;
    T : REAL;
    U : REAL;
END_VAR
VAR
    Temp : REAL;
END_VAR
Temp := X - T;
CAUCHY := MATH.PI_INV * U / (U * U + Temp * Temp);
END_FUNCTION

FUNCTION CAUCHYCD : REAL
VAR_INPUT
    X : REAL;
    T : REAL;
    U : REAL;
END_VAR
CAUCHYCD := 0.5 + MATH.PI_INV * ATAN((X - T) / U);
END_FUNCTION

FUNCTION CEIL : INT
VAR_INPUT
    X : REAL;
END_VAR
CEIL := REAL_TO_INT(X);
IF INT_TO_REAL(CEIL) < X THEN
    CEIL := CEIL + 1;
END_IF;
END_FUNCTION

FUNCTION CEIL2 : DINT
VAR_INPUT
    X : REAL;
END_VAR
CEIL2 := REAL_TO_DINT(X);
IF DINT_TO_REAL(CEIL2) < X THEN
    CEIL2 := CEIL2 + 1;
END_IF;
END_FUNCTION

FUNCTION CMP : BOOL
VAR_INPUT
    X : REAL;
    Y : REAL;
    N : INT;
END_VAR
VAR
    ScaleFactor : REAL;
    LogValue : REAL;
    DecadeExponent : INT;
    XDigits : DINT;
    YDigits : DINT;
END_VAR
ScaleFactor := ABS(X);
IF ScaleFactor > 0.0 THEN
    LogValue := LOG(ScaleFactor);
    DecadeExponent := FLOOR(X := LogValue) - N + 1;
    ScaleFactor := EXP10(X := INT_TO_REAL(DecadeExponent));
    XDigits := FLOOR2(X := X / ScaleFactor);
    YDigits := FLOOR2(X := Y / ScaleFactor);
    CMP := XDigits = YDigits;
ELSE
    CMP := X = Y;
END_IF;
END_FUNCTION

FUNCTION COSH : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    T : REAL;
END_VAR
T := EXP(X);
COSH := (1.0 / T + T) * 0.5;
END_FUNCTION

FUNCTION COTH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    COTH := 1.0;
ELSIF X < -20.0 THEN
    COTH := -1.0;
ELSE
    COTH := 1.0 + 2.0 / (EXP(X * 2.0) - 1.0);
END_IF;
END_FUNCTION

FUNCTION D_TRUNC : DINT
VAR_INPUT
    X : REAL;
END_VAR
D_TRUNC := REAL_TO_DINT(X);
IF X > 0.0 THEN
    IF DINT_TO_REAL(D_TRUNC) > X THEN
        D_TRUNC := D_TRUNC - 1;
    END_IF;
ELSE
    IF DINT_TO_REAL(D_TRUNC) < X THEN
        D_TRUNC := D_TRUNC + 1;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION DEC1 : INT
VAR_INPUT
    X : INT;
    N : INT;
END_VAR
IF X = 0 THEN
    DEC1 := N - 1;
ELSE
    DEC1 := X - 1;
END_IF;
END_FUNCTION

FUNCTION DEG : REAL
VAR_INPUT
    RAD : REAL;
END_VAR
DEG := MODR(IN := 57.29577951308232 * RAD, DIVI := 360.0);
END_FUNCTION

FUNCTION DIFFER : BOOL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    X : REAL;
END_VAR
DIFFER := ABS(IN1 - IN2) > X;
END_FUNCTION

FUNCTION ERF : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    X2 : REAL;
    AX2 : REAL;
END_VAR
X2 := X * X;
AX2 := 0.147 * X2 + 1.0;
ERF := SQRT(1.0 - EXP(-X2 * ((0.27323954473516 + AX2) / AX2))) * INT_TO_REAL(SGN(X := X));
END_FUNCTION

FUNCTION ERFC : REAL
VAR_INPUT
    X : REAL;
END_VAR
ERFC := 1.0 - ERF(X := X);
END_FUNCTION

FUNCTION EVEN : BOOL
VAR_INPUT
    IN : DINT;
END_VAR
EVEN := (IN MOD 2) = 0;
END_FUNCTION

FUNCTION EXP10 : REAL
VAR_INPUT
    X : REAL;
END_VAR
EXP10 := EXP(X * 2.30258509299405);
END_FUNCTION

FUNCTION EXPN : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    Base : REAL;
    Exponent : INT;
    NegativeExponent : BOOL;
END_VAR
Base := X;
Exponent := N;
NegativeExponent := Exponent < 0;
Exponent := ABS(Exponent);
IF (Exponent MOD 2) = 1 THEN
    EXPN := Base;
ELSE
    EXPN := 1.0;
END_IF;
Exponent := Exponent / 2;
WHILE Exponent > 0 DO
    Base := Base * Base;
    IF (Exponent MOD 2) = 1 THEN
        EXPN := EXPN * Base;
    END_IF;
    Exponent := Exponent / 2;
END_WHILE;
IF NegativeExponent THEN
    EXPN := 1.0 / EXPN;
END_IF;
END_FUNCTION

FUNCTION FACT : DINT
VAR_INPUT
    X : INT;
END_VAR
VAR
    I : INT;
END_VAR
IF X < 0 OR X > 12 THEN
    FACT := -1;
ELSIF X < 2 THEN
    FACT := 1;
ELSE
    FACT := 1;
    FOR I := 2 TO X DO
        FACT := FACT * INT_TO_DINT(I);
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION FIB : DINT
VAR_INPUT
    X : INT;
END_VAR
VAR
    WorkX : INT;
    T1 : DINT;
    T2 : DINT;
END_VAR
WorkX := X;
IF WorkX < 0 OR WorkX > 46 THEN
    FIB := -1;
ELSIF WorkX < 2 THEN
    FIB := INT_TO_DINT(WorkX);
ELSE
    T2 := 1;
    WHILE WorkX > 3 DO
        WorkX := WorkX - 2;
        T1 := T1 + T2;
        T2 := T1 + T2;
    END_WHILE;
    IF WorkX > 2 THEN
        T1 := T1 + T2;
    END_IF;
    FIB := T1 + T2;
END_IF;
END_FUNCTION

FUNCTION FLOOR : INT
VAR_INPUT
    X : REAL;
END_VAR
FLOOR := REAL_TO_INT(X);
IF INT_TO_REAL(FLOOR) > X THEN
    FLOOR := FLOOR - 1;
END_IF;
END_FUNCTION

FUNCTION FLOOR2 : DINT
VAR_INPUT
    X : REAL;
END_VAR
FLOOR2 := REAL_TO_DINT(X);
IF DINT_TO_REAL(FLOOR2) > X THEN
    FLOOR2 := FLOOR2 - 1;
END_IF;
END_FUNCTION

FUNCTION FRACT : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    IntegerPart : DINT;
END_VAR
IF ABS(X) < 2.0E9 THEN
    IntegerPart := D_TRUNC(X := X);
    FRACT := X - DINT_TO_REAL(IntegerPart);
ELSE
    FRACT := 0.0;
END_IF;
END_FUNCTION

FUNCTION GAMMA : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 0.0 THEN
    GAMMA := SQRT(MATH.PI2 / X) * EXPT(MATH.E_INV * (X + 1.0 / (12.0 * X - 0.1 / X)), X);
END_IF;
END_FUNCTION

FUNCTION GAUSS : REAL
VAR_INPUT
    X : REAL;
    U : REAL;
    SI : REAL;
END_VAR
VAR
    Temp : REAL;
    SIInv : REAL;
END_VAR
IF SI = 0.0 THEN
    GAUSS := 0.0;
ELSE
    Temp := X - U;
    SIInv := 1.0 / SI;
    GAUSS := EXP(Temp * Temp * SIInv * SIInv * -0.5) * 0.39894228 * SIInv;
END_IF;
END_FUNCTION

FUNCTION GAUSSCD : REAL
VAR_INPUT
    X : REAL;
    U : REAL;
    SI : REAL;
END_VAR
IF SI = 0.0 THEN
    IF X < U THEN
        GAUSSCD := 0.0;
    ELSE
        GAUSSCD := 1.0;
    END_IF;
ELSE
    GAUSSCD := (ERF(X := (X - U) / (SI * 1.414213562)) + 1.0) * 0.5;
END_IF;
END_FUNCTION

FUNCTION GCD : INT
VAR_INPUT
    A : DINT;
    B : DINT;
END_VAR
VAR
    Left : DINT;
    Right : DINT;
    Temp : DINT;
END_VAR
Left := ABS(A);
Right := ABS(B);
WHILE Right <> 0 DO
    Temp := Left MOD Right;
    Left := Right;
    Right := Temp;
END_WHILE;
GCD := DINT_TO_INT(Left);
END_FUNCTION

FUNCTION GDF : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    GDF := 0.0;
ELSIF X > 15.0 THEN
    GDF := MATH.PI05;
ELSIF X < -15.0 THEN
    GDF := -MATH.PI05;
ELSE
    GDF := ATAN(EXP(X)) * 2.0 - MATH.PI05;
END_IF;
END_FUNCTION

FUNCTION GOLD : REAL
VAR_INPUT
    X : REAL;
END_VAR
GOLD := (X + SQRT(X * X + 4.0)) * 0.5;
END_FUNCTION

FUNCTION HYPOT : REAL
