FUNCTION INC2 : INT
VAR_INPUT
    X : INT;
    D : INT;
    L : INT;
    U : INT;
END_VAR
VAR
    Span : INT;
END_VAR
Span := U - L + 1;
INC2 := (X + D - L + Span) MOD Span + L;
END_FUNCTION

FUNCTION INV : REAL
