END_IF;
END_FUNCTION

FUNCTION LAMBERT_W : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    W : REAL;
    NextW : REAL;
    We : REAL;
    W1e : REAL;
    Ewx : REAL;
    I : INT;
END_VAR
IF X < -0.367879441171442 THEN
    LAMBERT_W := -1000.0;
ELSIF X = 0.0 THEN
    LAMBERT_W := 0.0;
ELSE
    IF X <= 500.0 THEN
        W := LN(X + 1.0);
        W := 0.665 * (1.0 + 0.0195 * W) * W + 0.04;
    ELSE
        W := LN(X - 4.0) - (1.0 - 1.0 / LN(X)) * LN(LN(X));
    END_IF;
    FOR I := 0 TO 5 DO
        Ewx := EXP(W);
        We := W * Ewx - X;
        W1e := (W + 1.0) * Ewx;
        NextW := W - (We / (W1e - (W + 2.0) * We / (2.0 * W + 2.0)));
        IF ABS(NextW - W) < 1.0E-6 THEN
            W := NextW;
            EXIT;
        END_IF;
        W := NextW;
    END_FOR;
    LAMBERT_W := W;
END_IF;
END_FUNCTION

FUNCTION LANGEVIN : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    LANGEVIN := 0.0;
ELSE
    LANGEVIN := COTH(X := X) - 1.0 / X;
END_IF;
END_FUNCTION

FUNCTION MAX3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
