FUNCTION MID3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
VAR
    A : REAL;
    B : REAL;
END_VAR
A := IN1;
B := IN2;
IF A > B THEN
    MID3 := A;
    A := B;
    B := MID3;
END_IF;
IF B > IN3 THEN
    B := IN3;
END_IF;
MID3 := SEL(A > B, B, A);
END_FUNCTION

FUNCTION MIN3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
MIN3 := MIN(MIN(IN1, IN2), IN3);
END_FUNCTION

FUNCTION MODR : REAL
VAR_INPUT
    IN : REAL;
    DIVI : REAL;
END_VAR
VAR
    QuotientFloor : DINT;
END_VAR
IF DIVI = 0.0 THEN
    MODR := 0.0;
ELSE
    QuotientFloor := FLOOR2(X := IN / DIVI);
    MODR := IN - DINT_TO_REAL(QuotientFloor) * DIVI;
END_IF;
END_FUNCTION

FUNCTION MUL_ADD : REAL
VAR_INPUT
    X : REAL;
    K : REAL;
    O : REAL;
END_VAR
MUL_ADD := X * K + O;
