END_VAR
SIGN_R := IN < 0.0;
END_FUNCTION

FUNCTION SINC : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    SINC := 1.0;
ELSE
    SINC := SIN(X) / X;
END_IF;
END_FUNCTION

FUNCTION SINH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF ABS(X) < 2.0E-3 THEN
    SINH := X;
ELSE
    SINH := (EXP(X) - EXP(-X)) * 0.5;
END_IF;
END_FUNCTION

FUNCTION SQRTN : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
IF N > 0 THEN
    IF X = 0.0 THEN
        SQRTN := 0.0;
    ELSIF X > 0.0 THEN
        SQRTN := EXP(LN(X) / INT_TO_REAL(N));
    ELSE
        SQRTN := 0.0;
    END_IF;
ELSE
    SQRTN := 0.0;
END_IF;
END_FUNCTION

FUNCTION TANC : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    TANC := 1.0;
ELSE
    TANC := TAN(X) / X;
END_IF;
END_FUNCTION

FUNCTION TANH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    TANH := 1.0;
ELSIF X < -20.0 THEN
    TANH := -1.0;
ELSE
    TANH := 1.0 - 2.0 / (EXP(2.0 * X) + 1.0);
END_IF;
END_FUNCTION

FUNCTION WINDOW : BOOL
VAR_INPUT
    LOW : REAL;
    IN : REAL;
    HIGH : REAL;
END_VAR
WINDOW := IN < HIGH AND IN > LOW;
