VAR
    ReadyValue : BOOL;
    ErrorValue : BOOL;
    ErrorIdValue : WORD;
    StatusValue : BYTE;
    OutputValue : REAL;
    TriggeredValue : BOOL;
    PeriodValue : TIME := T#1s;
