FUNCTION_BLOCK HYST
VAR_INPUT
	In : REAL;
	HIGH_LIMIT : REAL;
	LOW_LIMIT : REAL;
END_VAR
VAR_OUTPUT
	Q : BOOL;
	WIN : BOOL;
END_VAR
IF HIGH_LIMIT >= LOW_LIMIT THEN
	IF IN < LOW_LIMIT THEN
		Q := FALSE;
		WIN := FALSE;
	ELSIF IN > HIGH_LIMIT THEN
		Q := TRUE;
		WIN := FALSE;
	ELSE
		WIN := TRUE;
	END_IF;
ELSE
	IF IN > LOW_LIMIT THEN
		Q := FALSE;
		WIN := FALSE;
	ELSIF IN < HIGH_LIMIT THEN
		Q := TRUE;
		WIN := FALSE;
	ELSE
		WIN := TRUE;
	END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK HYST_1
VAR_INPUT
	In : REAL;
	high : REAL;
	low : REAL;
END_VAR
VAR_OUTPUT
	Q : BOOL;
	WIN : BOOL;
END_VAR
IF in < low THEN
	Q := FALSE;
	win := FALSE;
ELSIF in > high THEN
	Q := TRUE;
	win := FALSE;
ELSE
	win := TRUE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK HYST_2
VAR_INPUT
	IN : REAL;
	VAL : REAL;
	HYS : REAL;
END_VAR
VAR_OUTPUT
	Q : BOOL;
	WIN : BOOL;
END_VAR
VAR
	tmp: REAL;
END_VAR
tmp := val - hys * 0.5;
IF in < tmp THEN
	Q := FALSE;
	win := FALSE;
ELSIF in > tmp + hys THEN
	Q := TRUE;
	win := FALSE;
ELSE
	win := TRUE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK HYST_3
VAR_INPUT
	in : REAL;
	hyst : REAL;
	val1 : REAL;
	val2 : REAL;
END_VAR
VAR_OUTPUT
	Q1 : BOOL;
	Q2 : BOOL;
END_VAR
VAR
	X: REAL;
END_VAR
X := hyst * 0.5;
IF in < val1 - X THEN
	Q1 := TRUE;
ELSIF in > val1 + X THEN
	Q1 := FALSE;
END_IF;
IF in < val2 - X THEN
	Q2 := FALSE;
ELSIF in > val2 + X THEN
	Q2 := TRUE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTEGRATE
VAR_INPUT
	E : BOOL := TRUE;
	X : REAL;
	K : REAL := 1.0;
END_VAR
VAR_IN_OUT
	Y : REAL;
END_VAR
VAR
	X_last : REAL;
	init: BOOL;
	last: DWORD;
	tx: DWORD;
END_VAR
tx := T_PLC_MS();
IF NOT init THEN
	init := TRUE;
	X_last := X;
ELSIF E THEN
	Y := (X + X_LAST) * 0.5E-3 * UDINT_TO_REAL(DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last)) * K + Y;
	X_last := X;
END_IF;
last := tx;
END_FUNCTION_BLOCK

FUNCTION AIR_DENSITY : REAL
VAR_INPUT
    T : REAL;
    P : REAL;
    RH : REAL;
END_VAR
VAR CONSTANT
    RL : REAL := 287.05;
    RX : REAL := 3.773319E-3;
END_VAR
VAR
    SddValue : REAL;
END_VAR
SddValue := SDD(T + 0.0, TRUE);
AIR_DENSITY := phys.PN * (1.0 - RH * SddValue * RX / P) / (RL * (T - phys.T0));
END_FUNCTION

FUNCTION AIR_ENTHALPY : REAL
VAR_INPUT
    T : REAL;
    RH : REAL;
END_VAR
VAR CONSTANT
    CPL : REAL := 1.00482;
    CW : REAL := 1.86;
    LH : REAL := 2500.78;
END_VAR
VAR
    DewCondensation : REAL;
END_VAR
DewCondensation := DEW_CON(RH, T);
AIR_ENTHALPY := CPL * T + (CW * T + LH) * DewCondensation;
END_FUNCTION

FUNCTION_BLOCK BOILER
VAR_INPUT
	T_upper : REAL;
	T_lower : REAL;
	Pressure : BOOL := TRUE;
	enable : BOOL := TRUE;
	Req_1 : BOOL;
	Req_2 : BOOL;
	Boost : BOOL;
END_VAR
VAR_INPUT CONSTANT
	t_upper_min : REAL := 50.0;
	t_upper_max : REAL := 60.0;
	T_lower_enable : BOOL;
	T_lower_max : REAL := 60.0;
	T_request_1 : REAL := 70.0;
	T_request_2 : REAL := 50.0;
	T_request_hys : REAL := 5.0;
	T_protect_high : REAL := 80.0;
	T_protect_low : REAL := 10.0;
END_VAR
VAR_OUTPUT
	Heat : BOOL;
	error : BOOL;
	status : BYTE;
END_VAR
VAR
	edge: BOOL;
	boost_mode: BOOL;
	flag_0 : BOOL;
	flag_1: BOOL;
	flag_2: BOOL;
END_VAR
IF t_upper > t_protect_high THEN
	status := BYTE#1;
	heat := FALSE;
	error := TRUE;
ELSIF t_upper < t_protect_low THEN
	status := BYTE#2;
	heat :=	TRUE;
	error := TRUE;
ELSIF t_lower > T_protect_high AND t_lower_enable THEN
	status := BYTE#3;
	heat := FALSE;
	error := TRUE;
ELSIF t_lower < t_protect_low AND t_lower_enable THEN
	status := BYTE#4;
	heat := TRUE;
	error := TRUE;
ELSIF NOT pressure THEN
	status := BYTE#5;
	heat := FALSE;
	error := TRUE;
ELSIF req_1 OR req_2 OR enable OR boost THEN
	error := FALSE;
	IF boost AND NOT edge AND t_upper < t_upper_max THEN
		status := BYTE#101;
		heat := TRUE;
		boost_mode := TRUE;
	ELSIF enable AND t_upper < T_upper_min THEN
		status := BYTE#102;
		heat := TRUE;
	ELSIF req_1 AND t_upper < T_request_1 THEN
		status := BYTE#103;
		heat := TRUE;
	ELSIF req_2 AND t_upper < t_request_2 THEN
		status := BYTE#104;
		heat := TRUE;
	END_IF;
	IF heat THEN
		IF (enable OR boost_mode) THEN
			flag_0 := TRUE;
			IF T_lower_enable AND T_lower > T_lower_max THEN
				flag_0 := FALSE;
				boost_mode := FALSE;
			ELSIF NOT T_lower_enable AND T_upper > T_upper_max THEN
				flag_0 := FALSE;
				boost_mode := FALSE;
			END_IF;
		ELSE
			flag_0 := FALSE;
		END_IF;
		flag_1 := (req_1 AND T_upper > T_request_1 + T_request_hys) AND req_1;
		flag_2 := (req_2 AND T_upper > T_request_2 + T_request_hys) AND req_2;
		heat := flag_0 OR flag_1 OR flag_2;
		IF heat = FALSE THEN status := BYTE#100; END_IF;
	END_IF;
ELSE
	status := BYTE#100;
	heat := FALSE;
	error := FALSE;
END_IF;
edge := boost;
END_FUNCTION_BLOCK

FUNCTION_BLOCK BURNER
VAR_INPUT
	in : BOOL;
	stage2 : BOOL;
	over_temp : BOOL;
	oil_temp : BOOL := TRUE;
	Flame : BOOL;
	rst : BOOL;
	rst_timer : BOOL;
END_VAR
VAR_INPUT CONSTANT
	pre_heat_time : TIME := t#5s;
	pre_vent_time : TIME := t#15s;
	pre_ignite_time : TIME := t#5s;
	post_ignite_time : TIME := t#25s;
	stage2_delay : TIME := t#10s;
	safety_time : TIME := t#5s;
	lockout_time : TIME := t#10s;
	multiple_ignition : BOOL := TRUE;
	KW1 : REAL;
	KW2 : REAL;
END_VAR
VAR_OUTPUT
	motor : BOOL;
	coil1 : BOOL;
	coil2 : BOOL;
	pre_heat: BOOL;
	ignite : BOOL;
	KWh : REAL;
	status : BYTE;
	fail : BOOL;
END_VAR
VAR_IN_OUT
	runtime1 : UDINT;
	runtime2 : UDINT;
	cycles : UDINT;
END_VAR
VAR
	state : INT;
	last : DWORD;
	tx: DWORD;
	last_change: DWORD;
	timer1 : ONTIME;
	timer2 : ONTIME;
	oil_temp_last: BOOL;
	cycles2 : UDINT;
END_VAR
tx := T_PLC_MS();
IF rst OR over_temp OR state = 0 THEN
	IF status > BYTE#0 AND DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(lockout_time)) AND rst THEN
		status := BYTE#110;
		fail := FALSE;
		state := 1;
	ELSE
		motor := FALSE;
		coil1 := FALSE;
		coil2 := FALSE;
		ignite := FALSE;
		pre_heat := FALSE;
		IF over_temp THEN
			status := BYTE#9;
			fail := TRUE;
		END_IF;
		last_change := tx;
		last := tx;
		state := 1;
	END_IF;
END_IF;
IF rst_timer THEN
	runtime1 := 0;
	runtime2 := 0;
	cycles := 0;
	cycles2 := 0;
END_IF;
IF NOT ((status > BYTE#0 AND status < BYTE#100) OR rst) THEN
    CASE state OF
    1:
        IF in AND flame THEN
            state := 7;
            pre_heat := FALSE;
            status := BYTE#2;
            last_change := tx;
        ELSIF in THEN
            pre_heat := TRUE;
            state := 2;
            last_change := tx;
        END_IF;
    2:
        IF (DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(pre_heat_time)) AND oil_temp) OR (oil_temp AND NOT oil_temp_last) THEN
            motor := TRUE;
            state := 3;
            last_change := tx;
        ELSIF DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(pre_heat_time)) AND NOT oil_temp THEN
            state := 7;
            pre_heat := FALSE;
            status := BYTE#1;
            last_change := tx;
        ELSIF flame THEN
            state := 7;
            pre_heat := FALSE;
            status := BYTE#2;
            last_change := tx;
        END_IF;
    3:
        IF DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(pre_vent_time)) - DWORD_TO_UDINT(TIME_TO_DWORD(pre_ignite_time)) THEN
            ignite := TRUE;
            state := 4;
            last_change := tx;
        ELSIF flame THEN
            state := 7;
            pre_heat := FALSE;
            motor := FALSE;
            status := BYTE#3;
            last_change := tx;
        END_IF;
    4:
        IF DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(pre_ignite_time)) THEN
            coil1 := TRUE;
            state := 5;
            last_change := tx;
        END_IF;
    5:
        IF DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(safety_time)) OR flame THEN
            IF NOT flame THEN
                state := 7;
                motor := FALSE;
                coil1 := FALSE;
                pre_heat := FALSE;
                ignite := FALSE;
                status := BYTE#4;
                last_change := tx;
            ELSE
                state := 6;
                last_change := tx;
            END_IF;
        END_IF;
    6:
        IF NOT flame AND NOT multiple_ignition THEN
            state := 7;
            motor := FALSE;
            coil1 := FALSE;
            coil2 := FALSE;
            pre_heat := FALSE;
            ignite := FALSE;
            status := BYTE#5;
            last_change := tx;
        ELSIF NOT flame AND multiple_ignition THEN
            ignite := TRUE;
            state := 5;
            coil2 := FALSE;
            last_change := tx;
        ELSE
            IF DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(post_ignite_time)) THEN
                ignite := FALSE;
            END_IF;
            IF DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last_change) >= DWORD_TO_UDINT(TIME_TO_DWORD(stage2_delay)) AND stage2 THEN
                coil2 := TRUE;
            ELSE
                coil2 := FALSE;
            END_IF;
        END_IF;
    END_CASE;
    IF NOT in THEN
        state := 1;
        motor := FALSE;
        coil1 := FALSE;
        coil2 := FALSE;
        ignite := FALSE;
        pre_heat := FALSE;
        last_change := tx;
    END_IF;
    timer1(in := flame AND in AND motor AND coil1 AND NOT coil2, seconds := runtime1, cycles := cycles);
    timer2(in := flame AND in AND motor AND coil1 AND coil2, seconds := runtime2, cycles := cycles2);
    KWH := UDINT_TO_REAL(runtime1) * KW1 / 3600.0 + UDINT_TO_REAL(runtime2) * KW2 / 3600.0;
    last := tx;
    IF status > BYTE#0 AND status < BYTE#100 THEN
        fail := TRUE;
    ELSE
        fail := FALSE;
        IF NOT in THEN
            status := BYTE#110;
        ELSIF flame AND in AND motor AND coil2 AND coil1 THEN
            status := BYTE#113;
        ELSIF flame AND in AND motor AND coil1 THEN
            status := BYTE#112;
        ELSE
            status := BYTE#111;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION DEW_CON : REAL
VAR_INPUT
    RH : REAL;
    T : REAL;
END_VAR
VAR
    SddValue : REAL;
END_VAR
IF RH > 0.0 AND T > -50.0 THEN
    SddValue := SDD(T + 0.0, FALSE);
    DEW_CON := 2.166824303E-2 * RH * SddValue / (T - phys.T0);
ELSE
    DEW_CON := 0.0;
END_IF;
END_FUNCTION

FUNCTION DEW_RH : REAL
VAR_INPUT
    VC : REAL;
    T : REAL;
END_VAR
VAR
    DewCondensation : REAL;
END_VAR
DewCondensation := DEW_CON(1.0, T);
DEW_RH := LIMIT(0.0, VC / DewCondensation, 100.0);
END_FUNCTION


FUNCTION DEW_TEMP : REAL
VAR_INPUT
    RH : REAL;
    T : REAL;
END_VAR
VAR CONSTANT
    a : REAL := 7.5;
    b : REAL := 237.3;
END_VAR
VAR
    V : REAL;
    SaturationTerm : REAL;
END_VAR
IF rh > 0.0 THEN
    SaturationTerm := EXP10((a * T) / (b + T));
    V := LOG(RH * 0.01 * SaturationTerm);
    DEW_TEMP := b * V / (a - V);
ELSE
    DEW_TEMP := phys.T0;
END_IF;
END_FUNCTION

FUNCTION HEAT_INDEX : REAL
VAR_INPUT
	T : REAL;
	RH : REAL;
END_VAR
VAR
	RH2 : REAL;
	T2 : REAL;
	TF : REAL;
END_VAR
IF RH < 20.0 OR T < 20.0 THEN
	HEAT_INDEX := T;
ELSE
	RH2 := RH * RH;
	TF := C_TO_F(T);
	T2 := TF * TF;
	HEAT_INDEX := -42.379 + 2.04901523 * TF - 6.83783E-3 * T2
			+ RH * (10.1433127 - 0.22475541 * TF + 1.22874E-3 * T2)
			+ RH2 * (8.5282E-4 * TF - 5.481717E-2 - 1.99E-6 * T2);
	HEAT_INDEX := F_TO_C(HEAT_INDEX);
END_IF;
END_FUNCTION

FUNCTION_BLOCK HEAT_METER
VAR_INPUT
	TF, TR : REAL;
	LPH : REAL;
	E : BOOL;
	RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
	CP : REAL;
	Density : REAL;
	Content : REAL;
	Pulse_Mode : BOOL;
	Return_meter : BOOL;
	AVG_time : TIME := T#5s;
END_VAR
VAR_OUTPUT
	C : REAL;
END_VAR
VAR_IN_OUT
	Y : REAL;
END_VAR
VAR
	tx, last : DWORD;
	int1 : FT_INT2;
	edge : BOOL;
	x: REAL;
	init: BOOL;
	y_last: REAL;
END_VAR
IF rst THEN
	int1(rst := TRUE);
	C := 0.0;
	Y := 0.0;
ELSIF e THEN
	X := (WATER_DENSITY(SEL(return_meter, TF, TR), FALSE) * (WATER_ENTHALPY(TF) - WATER_ENTHALPY(TR)) * (1.0 - content) + CP * Density * content * (TF-TR));
END_IF;
int1(run := NOT pulse_mode AND e, in := X * LPH * 2.77777777777E-4);
IF pulse_mode THEN
	IF NOT edge AND E THEN Y := Y + X * LPH; END_IF;
ELSE
	Y := int1.Out;
END_IF;
edge := e;
tx := T_PLC_MS();
IF NOT init THEN
	init := TRUE;
	last := tx;
END_IF;
IF (DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last) >= DWORD_TO_UDINT(TIME_TO_DWORD(AVG_TIME))) AND (avg_time > T#0s) THEN
	last := tx;
	C := (Y - Y_last) * 3.6E6 / DWORD_TO_REAL(TIME_TO_DWORD(AVG_TIME));
	Y_last := Y;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK HEAT_TEMP
VAR_INPUT
	T_EXT : REAL;
	T_INT : REAL;
	OFFSET : REAL;
	T_REQ : REAL;
END_VAR
VAR_INPUT CONSTANT
	TY_MAX : REAL := 70.0;
	TY_MIN : REAL := 25.0;
	TY_CONFIG : REAL := 70.0;
	T_INT_CONFIG : REAL := 20.0;
	T_EXT_CONFIG : REAL := -15.0;
	T_DIFF : REAL := 10.0;
	C : REAL := 1.33;
	H : REAL := 3.0;
END_VAR
VAR_OUTPUT
	TY : REAL;
	HEAT : BOOL;
END_VAR
VAR
	tr : REAL;
	tx: REAL;
END_VAR
tr := T_INT + OFFSET;
tx := (tr - T_EXT) / (T_INT_CONFIG - T_EXT_CONFIG);
IF T_EXT + H > tr THEN
	TY := 0.0;
ELSE
	TY := LIMIT(TY_MIN, tr + T_DIFF * 0.5 * tx + (TY_CONFIG - T_DIFF * 0.5 - tr) * EXPT(tx, 1.0 / C), TY_MAX);
END_IF;
TY := MAX(TY, T_REQ);
HEAT := TY > 0.0;
END_FUNCTION_BLOCK

FUNCTION_BLOCK LEGIONELLA
VAR_INPUT
