	DELAY4 := TP_4,
	WAIT5 := T_max_ret,
	DELAY5 := TP_5,
	WAIT6 := T_max_ret,
	DELAY6 := TP_6,
	WAIT7 := T_max_ret,
	DELAY7 := TP_7
);
IF X1.Q OR MANUAL OR x2.run THEN
