Tx := DWORD_TO_DINT(T_PLC_US());
IF NOT Init THEN
    Init := TRUE;
    TC := REAL#0.0;
ELSE
    TC := DINT_TO_REAL(Tx - Last) * 1.0E-6;
END_IF;
Last := Tx;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TC_US
VAR_OUTPUT
    TC : DWORD;
END_VAR
VAR
    Init : BOOL;
