(* OSCAT BASIC 3.33 device-driver helpers. *)

FUNCTION_BLOCK DRIVER_1
VAR_INPUT CONSTANT
	Toggle_Mode : BOOL;
	Timeout : TIME;
END_VAR
VAR_INPUT
	SET_REQ : BOOL;
	IN : BOOL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	Q : BOOL;
END_VAR
VAR
	off : TON;
	edge: BOOL;
END_VAR
IF off.Q THEN Q := FALSE; END_IF;
IF rst THEN
	Q := FALSE;
ELSIF SET_REQ THEN
	Q := TRUE;
ELSIF IN AND NOT edge THEN
	IF toggle_mode THEN q := NOT Q; ELSE q := TRUE; END_IF;
END_IF;
edge := in;
IF timeout > t#0s THEN off(in := Q, PT := Timeout); END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK DRIVER_4
VAR_INPUT CONSTANT
	Toggle_Mode : BOOL;
	Timeout : TIME;
END_VAR
VAR_INPUT
	SET_REQ : BOOL;
	IN0, IN1, IN2, IN3 : BOOL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	Q0, Q1, Q2, Q3 : BOOL;
END_VAR
VAR
	d0, d1, d2, d3 : DRIVER_1;
END_VAR
D0(SET_REQ := SET_REQ, IN := IN0, RST := RST, Toggle_Mode := Toggle_Mode, Timeout := Timeout);
D1(SET_REQ := SET_REQ, IN := IN1, RST := RST, Toggle_Mode := Toggle_Mode, Timeout := Timeout);
D2(SET_REQ := SET_REQ, IN := IN2, RST := RST, Toggle_Mode := Toggle_Mode, Timeout := Timeout);
D3(SET_REQ := SET_REQ, IN := IN3, RST := RST, Toggle_Mode := Toggle_Mode, Timeout := Timeout);
Q0 := D0.Q;
Q1 := D1.Q;
Q2 := D2.Q;
Q3 := D3.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK DRIVER_4C
VAR_INPUT
    IN : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    Timeout : TIME;
END_VAR
VAR_OUTPUT
    SN : INT;
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
END_VAR
VAR
    off : TON;
    edge : BOOL;
END_VAR
IF RST OR off.Q THEN
    SN := 0;
ELSIF IN AND NOT edge THEN
    SN := SN + 1;
    IF SN > 4 THEN
        SN := 0;
    END_IF;
END_IF;
edge := IN;
Q0 := FALSE;
Q1 := FALSE;
Q2 := FALSE;
Q3 := FALSE;
CASE SN OF
    1:
        Q0 := TRUE;
    2:
        Q0 := TRUE;
        Q1 := TRUE;
    3:
        Q0 := TRUE;
        Q1 := TRUE;
        Q2 := TRUE;
    4:
        Q0 := TRUE;
        Q1 := TRUE;
        Q2 := TRUE;
        Q3 := TRUE;
END_CASE;
IF Timeout > T#0s THEN
    off(IN := SN > 0, PT := Timeout);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FLOW_CONTROL
VAR_INPUT
    IN : BOOL;
    REQ : BOOL;
    ENQ : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    T_AUTO : TIME := T#1h;
    T_DELAY : TIME := T#23h;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    STATUS : BYTE;
END_VAR
VAR
    timer : TP_1D;
    TimerReq : BOOL;
END_VAR
STATUS := BYTE#100;
TimerReq := FALSE;
IF RST THEN
    Q := FALSE;
    STATUS := BYTE#103;
ELSIF ENQ THEN
    IF IN THEN
        STATUS := BYTE#101;
    END_IF;
    IF REQ THEN
        TimerReq := TRUE;
        STATUS := BYTE#102;
    END_IF;
END_IF;
timer(IN := TimerReq, PT1 := T_AUTO, PTD := T_DELAY, RST := RST);
Q := (IN AND ENQ) OR timer.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_Profile
VAR_INPUT
    K : REAL := 1.0;
    O : REAL;
    M : REAL := 1.0;
    E : BOOL;
END_VAR
VAR_INPUT CONSTANT
    value_0 : REAL;
    time_1 : TIME;
    value_1 : REAL;
    time_2 : TIME;
    value_2 : REAL;
    time_3 : TIME;
    value_3 : REAL;
    time_10 : TIME;
    value_10 : REAL;
    time_11 : TIME;
    value_11 : REAL;
    time_12 : TIME;
    value_12 : REAL;
    time_13 : TIME;
    value_13 : REAL;
END_VAR
VAR_OUTPUT
    Y : REAL;
    RUN : BOOL;
    ET : TIME;
END_VAR
VAR
    tx : DWORD;
    edge : BOOL;
    state : INT;
    ta : DWORD;
    tb : DWORD;
    t0 : DWORD;
    temp : REAL;
    va : REAL;
    vb : REAL;
    ElapsedMs : UDINT;
END_VAR

tx := T_PLC_MS();
IF E AND NOT edge THEN
    RUN := TRUE;
    ET := T#0s;
    t0 := tx;
    ta := tx;
    tb := TIME_TO_DWORD(multime(time_1, M));
    va := value_0;
    vb := value_1;
    temp := value_0;
    state := 1;
END_IF;
edge := E;
IF run THEN
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(ta);
    CASE state OF
        1:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_2, time_1), M));
                va := value_1;
                vb := value_2;
                temp := value_1;
                state := 2;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        2:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_3, time_2), M));
                va := value_2;
                vb := value_3;
                temp := value_2;
                state := 3;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        3:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_10, time_3), M));
                va := value_3;
                vb := value_10;
                temp := value_3;
                state := 4;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        4:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_11, time_10), M));
                va := value_10;
                vb := value_11;
                temp := value_10;
                IF E THEN
                    state := 5;
                ELSE
                    state := 6;
                END_IF;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        5:
            IF E THEN
                ta := tx;
            ELSE
                state := 6;
            END_IF;
        6:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_12, time_11), M));
                va := value_11;
                vb := value_12;
                temp := value_11;
                state := 7;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        7:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_13, time_12), M));
                va := value_12;
                vb := value_13;
                temp := value_12;
                state := 8;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        8:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                temp := value_13;
                run := FALSE;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
    END_CASE;
    Y := temp * K + O;
    ET := DWORD_TO_TIME(UDINT_TO_DWORD(DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(t0)));
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INC_DEC
VAR_INPUT
	CHa : BOOL;
	CHb : BOOL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	dir : BOOL;
	cnt : INT;
END_VAR
VAR
	edgea : BOOL;
	clk: BOOL;
	clka: BOOL;
	clkb: BOOL;
	edgeb: BOOL;
	axb: BOOL;
END_VAR
axb := cha XOR chb;
clka := cha XOR edgea;
edgea := cha;
clkb := chb XOR edgeb;
edgeb := chb;
clk := clka OR clkb;
IF axb AND clka THEN dir := TRUE; END_IF;
IF axb AND clkb THEN dir := FALSE; END_IF;
IF clk AND dir THEN cnt := cnt + 1; END_IF;
IF clk AND NOT dir THEN cnt := cnt -1; END_IF;
IF rst THEN cnt := 0; END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTERLOCK
