END_VAR
VAR
	T1, T2 : TOF;
END_VAR
T1(IN := I1, PT := TL);
T2(IN := I2, PT := TL);
Q1 := I1 AND NOT t2.Q;
Q2 := I2 AND NOT t1.Q;
