FUNCTION_BLOCK PARSET
VAR_INPUT
    A0, A1 : BOOL;
END_VAR
VAR_INPUT CONSTANT
    X01, X02, X03, X04 : REAL;
    X11, X12, X13, X14 : REAL;
    X21, X22, X23, X24 : REAL;
    X31, X32, X33, X34 : REAL;
    TC : TIME;
END_VAR
VAR_OUTPUT
    P1, P2, P3, P4 : REAL;
END_VAR
VAR
    X : ARRAY[0..3,1..4] OF REAL;
    S1, S2, S3, S4 : REAL;
    tx, last : DWORD;
    start : BOOL;
    SetIndex : INT;
    LastA0 : BOOL;
    LastA1 : BOOL;
    init : BOOL;
    DurationMs : UDINT;
    ElapsedMs : UDINT;
    RemainingMs : UDINT;
END_VAR

tx := T_PLC_MS();
DurationMs := DWORD_TO_UDINT(TIME_TO_DWORD(TC));
IF NOT init THEN
    LastA0 := NOT A0;
    LastA1 := A1;
    init := TRUE;
    X[0,1] := X01;
    X[0,2] := X02;
    X[0,3] := X03;
    X[0,4] := X04;
    X[1,1] := X11;
    X[1,2] := X12;
    X[1,3] := X13;
    X[1,4] := X14;
    X[2,1] := X21;
    X[2,2] := X22;
    X[2,3] := X23;
    X[2,4] := X24;
    X[3,1] := X31;
    X[3,2] := X32;
    X[3,3] := X33;
    X[3,4] := X34;
    SetIndex := 0;
    P1 := X01;
    P2 := X02;
    P3 := X03;
    P4 := X04;
END_IF;
IF (A0 <> LastA0) OR (A1 <> LastA1) THEN
    LastA0 := A0;
    LastA1 := A1;
    SetIndex := BOOL_TO_INT(A0) + BOOL_TO_INT(A1) * 2;
    IF DurationMs > UDINT#0 THEN
        start := TRUE;
        last := tx;
        S1 := (X[SetIndex,1] - P1) / UDINT_TO_REAL(DurationMs);
        S2 := (X[SetIndex,2] - P2) / UDINT_TO_REAL(DurationMs);
        S3 := (X[SetIndex,3] - P3) / UDINT_TO_REAL(DurationMs);
        S4 := (X[SetIndex,4] - P4) / UDINT_TO_REAL(DurationMs);
    ELSE
        start := FALSE;
        P1 := X[SetIndex,1];
        P2 := X[SetIndex,2];
        P3 := X[SetIndex,3];
        P4 := X[SetIndex,4];
    END_IF;
ELSIF start THEN
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(last);
    IF ElapsedMs < DurationMs THEN
        RemainingMs := DurationMs - ElapsedMs;
        P1 := X[SetIndex,1] - S1 * UDINT_TO_REAL(RemainingMs);
        P2 := X[SetIndex,2] - S2 * UDINT_TO_REAL(RemainingMs);
        P3 := X[SetIndex,3] - S3 * UDINT_TO_REAL(RemainingMs);
        P4 := X[SetIndex,4] - S4 * UDINT_TO_REAL(RemainingMs);
    ELSE
        start := FALSE;
        P1 := X[SetIndex,1];
        P2 := X[SetIndex,2];
        P3 := X[SetIndex,3];
        P4 := X[SetIndex,4];
    END_IF;
ELSE
    P1 := X[SetIndex,1];
    P2 := X[SetIndex,2];
    P3 := X[SetIndex,3];
    P4 := X[SetIndex,4];
END_IF;
END_FUNCTION_BLOCK

